-- Reproducible data corrections for vehicle-specific brevetto question banks.
-- Keep the active bank at 30 physics / 40 technical / 30 regulations per vehicle.
BEGIN;
UPDATE public.vehicle_brevetto_question_bank AS b
SET prompt=v.prompt,
    options=v.options::jsonb,
    correct_index=v.correct_index,
    explanation=v.explanation,
    source_url=v.source_url,
    source_note=v.source_note
FROM (VALUES
('01cf5131-fd31-40f9-843a-8f406408bc06','Qual è la funzione del motorino di avviamento?','["Azionare il servofreno in marcia","Raffreddare il motore","Regolare il rapporto del cambio","Far ruotare il motore termico fino all’avviamento autonomo"]',3,'Motorino e circuito di avviamento.','https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA','Documentazione ufficiale e risorse per il proprietario Subaru Crosstrek'),
('035f0029-816b-470a-b6ba-221453fee46a','Quale architettura adotta il motore termico 2.0 del sistema e-BOXER della Subaru Crosstrek?','["Quattro cilindri in linea longitudinale","Sei cilindri a V","Quattro cilindri orizzontali contrapposti (boxer)","Tre cilindri in linea"]',2,'La scheda ufficiale Subaru Italia descrive il propulsore e-BOXER con motore benzina 2,0 litri a quattro cilindri orizzontali contrapposti, a iniezione diretta.','https://www.subaru.it/news/nuova-subaru-crosstrek/','Subaru Italia: architettura del motore e-BOXER'),
('040fb963-6981-4e37-ac7d-40fc907a06f7','Qual è la funzione del catalizzatore?','["Filtrare l’olio motore","Raffreddare il carburante","Favorire la trasformazione chimica di inquinanti presenti nei gas di scarico","Aumentare la coppia alle ruote"]',2,'Trattamento catalitico dei gas di scarico.','https://www.landrover.it/defender/defender-110/models-and-specifications.html','Specifiche ufficiali Land Rover Defender 110; dotazioni da verificare in base all’allestimento'),
('0924e325-e2eb-4c68-ba1d-05f6720688f2','Qual è la funzione del differenziale su un asse motore?','["Aumentare la pressione dell’olio","Consentire alle ruote dello stesso asse di ruotare a velocità diverse in curva","Frenare automaticamente il veicolo","Bloccare sempre le due ruote alla stessa velocità"]',1,'Differenziale e cinematica in curva.','https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA','Documentazione ufficiale e risorse per il proprietario Subaru Crosstrek'),
('09c30fca-77fc-4c92-bbb8-9b7a568d701c','Qual è il compito del filtro carburante?','["Trattenere impurità e, nei sistemi previsti, separare l’acqua dal carburante","Aumentare il numero di ottani","Raffreddare il serbatoio","Misurare il livello dell’olio"]',0,'Filtrazione carburante e separazione dell’acqua.','https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA','Documentazione ufficiale e risorse per il proprietario Subaru Crosstrek'),
('0b74b9b7-1b36-4167-b6da-81a254f28bb4','Qual è la funzione primaria dell’olio motore?','["Comandare l’ABS","Lubrificare le parti in movimento e contribuire alla protezione dall’usura","Raffreddare direttamente i freni","Aumentare la pressione degli pneumatici"]',1,'Lubrificazione motore e manutenzione secondo manuale del costruttore.','https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA','Documentazione ufficiale e risorse per il proprietario Subaru Crosstrek'),
('0bbea617-f07b-4d58-8f28-19add11f5f0e','Da quando sono entrati in servizio i Guardacoste classe Bigliani?','["Dal 1980","Dal 1997","Dal 2008","Dal 2014"]',1,'La scheda GdF riporta l''entrata in servizio dei Guardacoste Bigliani a partire dal 1997.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/guardacoste/guardacoste-classe-bigliani','GdF - periodo di entrata in servizio classe Bigliani'),
('0d8f65ec-2c61-4a7e-ac26-334222289155','A cosa serve la pompa dell’acqua del motore?','["Azionare il differenziale","Far circolare il refrigerante nel circuito","Comprimere l’aria nei pneumatici","Regolare la convergenza"]',1,'Pompa e circolazione del liquido refrigerante.','https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA','Documentazione ufficiale e risorse per il proprietario Subaru Crosstrek'),
('0f83f532-c4bb-4af6-a988-77749b1f2e06','Qual è la velocità massima dichiarata per i pattugliatori classe Monti?','["18 nodi","28 nodi","35 nodi","43 nodi"]',1,'La scheda ufficiale del Servizio Navale indica una velocità di 28 nodi, anche in condizioni di mare agitato.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/pattugliatore/pattugliatore-classe-monti','GdF - dati prestazionali classe Monti'),
('14625c2c-a3c0-4c8b-992d-dc2a6186f4be','Come viene azionato un turbocompressore tradizionale?','["Dalla pompa ABS","Dal motorino dei tergicristalli","Dalla rotazione delle ruote posteriori","Dall’energia dei gas di scarico che mette in rotazione la turbina collegata al compressore"]',3,'Turbocompressore a gas di scarico.','https://www.jeep.com/content/dam/cross-regional/stellantis/jeep/latam-rol/colombia/es_co/manuales-propietarios/2024-manual-wrangler-jl-20l-ok.pdf','Manuale ufficiale Jeep Wrangler 2024'),
('1c421f12-1a2d-41ea-a2b7-98bbdf14bb8d','Quali sistemi coordina X-MODE sulla Subaru Crosstrek per migliorare la trazione su fondi difficili?','["Solo il climatizzatore e il sistema audio","Motore, trasmissione, trazione integrale e freni","Esclusivamente gli airbag","Solo il sistema di illuminazione"]',1,'Subaru Italia indica che X-MODE coordina motore, trasmissione, trazione integrale e freni; comprende inoltre l''Hill Descent Control per le discese ripide.','https://www.subaru.it/news/nuova-subaru-crosstrek/','Subaru Italia: X-MODE e Hill Descent Control'),
('2e4dbdbf-11b2-43f7-ac7e-6573c34a1132','A cosa serve il liquido refrigerante nel circuito motore?','["A regolare la pressione degli pneumatici","A lubrificare il cambio","A pulire il filtro aria","A trasferire calore e proteggere il circuito da corrosione e gelo secondo specifica"]',3,'Circuito di raffreddamento e specifica del refrigerante.','https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA','Documentazione ufficiale e risorse per il proprietario Subaru Crosstrek'),
('33e3ab2b-81e2-426c-9f58-f37dd4884d19','Quale funzione svolge la posizione 4L della scatola di trasferimento della Jeep Wrangler?','["Aumenta la velocità massima su asfalto","Fornisce maggiore trazione e controllo a bassa velocità su fondi difficili e pendenze","Disattiva permanentemente l’asse anteriore","Sostituisce il freno di stazionamento"]',1,'Il manuale Wrangler 2024 indica che il rapporto 4L serve per ottenere trazione e controllo aggiuntivi su terreni difficili, salite e discese ripide, aumentando la capacità di trazione a bassa velocità.','https://www.jeep.com/content/dam/cross-regional/stellantis/jeep/latam-rol/colombia/es_co/manuales-propietarios/2024-manual-wrangler-jl-20l-ok.pdf','Jeep - Manuale Wrangler 2024, uso della gamma 4L'),
('3d2eb895-56e8-4326-9946-085302f3a48a','A cosa serve il riduttore/invertitore in una trasmissione marina con linea d’asse?','["A collegare o disinnestare la propulsione, selezionare avanti/folle/indietro e adattare il regime dell’elica a quello del motore","A comandare i fanali di navigazione","A misurare la profondità del fondale","A raffreddare direttamente lo scafo"]',0,'Il riduttore/invertitore trasmette la potenza del motore alla linea d’asse, consente la selezione delle marce avanti, folle e indietro e riduce il regime in funzione dell’elica e della trasmissione.','https://www.volvopenta.com/support/product-family/md22%20%28inb%29/','Volvo Penta - documentazione trasmissioni marine entrobordo'),
('3fbf0d50-f5f2-4b46-94a6-59c0b21e68d6','Qual è la funzione della girante nella pompa dell’acqua di raffreddamento di un motore entrobordo?','["Generare il flusso del liquido o dell’acqua previsto dal circuito di raffreddamento","Regolare la tensione della cinghia di ormeggio","Comandare il timone","Filtrare il carburante"]',0,'La girante è l’elemento rotante della pompa che mette in movimento il fluido nel circuito di raffreddamento. Tipo e intervalli di sostituzione dipendono dal motore installato.','https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf','Volvo Penta - pompe e circuiti di raffreddamento marino'),
('4782c2f9-8ee9-49b3-a0ff-75e5034f2b30','A cosa serve la pompa dell’acqua del motore?','["Comprimere l’aria nei pneumatici","Regolare la convergenza","Azionare il differenziale","Far circolare il refrigerante nel circuito"]',3,'Pompa e circolazione del liquido refrigerante.','https://www.landrover.it/defender/defender-110/models-and-specifications.html','Specifiche ufficiali Land Rover Defender 110; dotazioni da verificare in base all’allestimento'),
('486f2bad-f59b-4fc1-9497-4adfab9a8208','A cosa serve la pompa dell’acqua del motore?','["Comprimere l’aria nei pneumatici","Regolare la convergenza","Azionare il differenziale","Far circolare il refrigerante nel circuito"]',3,'Pompa e circolazione del liquido refrigerante.','https://www.jeep.com/content/dam/cross-regional/stellantis/jeep/latam-rol/colombia/es_co/manuales-propietarios/2024-manual-wrangler-jl-20l-ok.pdf','Manuale ufficiale Jeep Wrangler 2024'),
('48c63e85-9139-4a87-9b0b-c8f230ef9146','Qual è la funzione della girante nella pompa dell’acqua di raffreddamento di un motore entrobordo?','["Generare il flusso del liquido o dell’acqua previsto dal circuito di raffreddamento","Regolare la tensione della cinghia di ormeggio","Comandare il timone","Filtrare il carburante"]',0,'La girante è l’elemento rotante della pompa che mette in movimento il fluido nel circuito di raffreddamento. Tipo e intervalli di sostituzione dipendono dal motore installato.','https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf','Volvo Penta - pompe e circuiti di raffreddamento marino'),
('48f0c7d8-7d52-4b04-b875-85a2aa2230fa','Qual è il compito principale dell’alternatore?','["Alimentare l’impianto elettrico e ricaricare la batteria durante il funzionamento","Avviare meccanicamente il motore a freddo","Modificare il rapporto del cambio","Raffreddare l’olio motore"]',0,'Alternatore e circuito di ricarica.','https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA','Documentazione ufficiale e risorse per il proprietario Subaru Crosstrek'),
('4945b55c-4e54-424f-8a01-47fb9c44aed1','Perché, prima della navigazione, il carico e le attrezzature di bordo devono essere distribuiti e fissati correttamente?','["Distribuire il peso in modo equilibrato, mantenerlo basso e fissare le attrezzature per impedirne lo spostamento","Concentrare tutto il carico a poppa per aumentare la velocità","Sistemare gli oggetti più pesanti in alto e su un solo lato","Lasciare libero il carico di muoversi per compensare il rollio"]',0,'La guida della U.S. Coast Guard prescrive di distribuire il carico in modo equilibrato, mantenerlo basso e fissare gli oggetti per impedirne lo spostamento: un carico eccessivo o mobile può compromettere assetto e stabilità.','https://www.uscg.mil/Portals/0/BoatingSafety/DOCS/Boaters-Guide-to-Federal-Requirements-for-Receational-Boats-20231108.pdf','U.S. Coast Guard - Safe Loading, 33 CFR 183 Subpart C'),
('4db31e31-14bb-475e-94d4-f79feaa34681','Quante unità comprende complessivamente la classe Bigliani e in quante serie?','["7 unità in due serie","19 unità in tre serie (III, VI e VIII)","2 unità in una serie","12 unità in quattro serie"]',1,'La scheda GdF indica 19 unità complessive della classe, distinte nelle serie III, VI e VIII. Il dato è riferito alla classe nel suo insieme, non alla sola VIII serie.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/guardacoste/guardacoste-classe-bigliani','GdF - composizione complessiva classe Bigliani'),
('4f217d05-2cb2-4036-852e-34e8b56a7689','Qual è la lunghezza del battello B.S.O. 139 indicata dalla Guardia di Finanza?','["8 metri","9,5 metri","11 metri","14 metri"]',2,'La notizia ufficiale GdF indica una lunghezza di 11 metri per il B.S.O. 139.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/notizie-ed-eventi/notizie-servizio-navale/anno-2026/potenziata-la-dotazione-di-mezzi-della-2a-squadra-unita-navali-di-vieste-con-lassegnazione-di-un-nuovo-battello-operativo','GdF - dimensioni B.S.O. 139'),
('50422d81-c244-4778-8e15-25229d460105','Perché il circuito di aspirazione dell’acqua di mare di un motore entrobordo deve essere controllato prima della partenza?','["Per verificare che presa, filtro e passaggi non siano ostruiti e che il raffreddamento possa funzionare","Per aumentare la pressione del carburante","Per regolare la bussola","Per lubrificare l’invertitore"]',0,'Un’ostruzione nella presa o nel filtro dell’acqua di mare può ridurre il raffreddamento e provocare surriscaldamento. Il controllo va eseguito secondo la procedura del costruttore dell’apparato installato.','https://www.volvopenta.com/support/product-family/md22%20%28inb%29/','Volvo Penta - documentazione motori marini entrobordo'),
('579edbfa-2fab-4790-8b68-a77d411e7fff','A cosa serve il riduttore/invertitore in una trasmissione marina con linea d’asse?','["A collegare o disinnestare la propulsione, selezionare avanti/folle/indietro e adattare il regime dell’elica a quello del motore","A comandare i fanali di navigazione","A misurare la profondità del fondale","A raffreddare direttamente lo scafo"]',0,'Il riduttore/invertitore trasmette la potenza del motore alla linea d’asse, consente la selezione delle marce avanti, folle e indietro e riduce il regime in funzione dell’elica e della trasmissione.','https://www.volvopenta.com/support/product-family/md22%20%28inb%29/','Volvo Penta - documentazione trasmissioni marine entrobordo'),
('57d95a72-4128-4d86-8c0b-41c86d103451','Perché, prima della navigazione, il carico e le attrezzature di bordo devono essere distribuiti e fissati correttamente?','["Distribuire il peso in modo equilibrato, mantenerlo basso e fissare le attrezzature per impedirne lo spostamento","Concentrare tutto il carico a poppa per aumentare la velocità","Sistemare gli oggetti più pesanti in alto e su un solo lato","Lasciare libero il carico di muoversi per compensare il rollio"]',0,'La guida della U.S. Coast Guard prescrive di distribuire il carico in modo equilibrato, mantenerlo basso e fissare gli oggetti per impedirne lo spostamento: un carico eccessivo o mobile può compromettere assetto e stabilità.','https://www.uscg.mil/Portals/0/BoatingSafety/DOCS/Boaters-Guide-to-Federal-Requirements-for-Receational-Boats-20231108.pdf','U.S. Coast Guard - Safe Loading, 33 CFR 183 Subpart C'),
('59a67cff-79e1-4053-9e97-668d3be7c74d','Quali materiali sono indicati per scafo e sovrastrutture della classe Monti?','["Scafo in acciaio ad alta resistenza e sovrastrutture in lega leggera","Scafo in legno e sovrastrutture in vetroresina","Scafo in alluminio e sovrastrutture in ghisa","Scafo in vetroresina e sovrastrutture in legno"]',0,'La scheda GdF specifica scafo in acciaio ad elevata resistenza e sovrastrutture in lega leggera. In sede di presa in carico, il dato aiuta a orientare il controllo visivo delle superfici e delle eventuali anomalie, senza sostituire la documentazione tecnica dell''unità.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/pattugliatore/pattugliatore-classe-monti','GdF - materiali costruttivi classe Monti'),
('61857324-249b-4785-a5a0-3347f253fd4a','Qual è la funzione dell’intercooler nei motori sovralimentati che ne sono dotati?','["Filtrare l’olio del cambio","Raffreddare l’aria compressa prima dell’aspirazione, aumentando la densità della carica","Ridurre la pressione degli pneumatici","Aumentare la temperatura dell’aria compressa"]',1,'Intercooler e temperatura dell’aria di aspirazione.','https://www.jeep.com/content/dam/cross-regional/stellantis/jeep/latam-rol/colombia/es_co/manuales-propietarios/2024-manual-wrangler-jl-20l-ok.pdf','Manuale ufficiale Jeep Wrangler 2024'),
('61bac78a-9e03-4c86-b1d9-472b174cc8f4','Perché, prima della navigazione, il carico e le attrezzature di bordo devono essere distribuiti e fissati correttamente?','["Distribuire il peso in modo equilibrato, mantenerlo basso e fissare le attrezzature per impedirne lo spostamento","Concentrare tutto il carico a poppa per aumentare la velocità","Sistemare gli oggetti più pesanti in alto e su un solo lato","Lasciare libero il carico di muoversi per compensare il rollio"]',0,'La guida della U.S. Coast Guard prescrive di distribuire il carico in modo equilibrato, mantenerlo basso e fissare gli oggetti per impedirne lo spostamento: un carico eccessivo o mobile può compromettere assetto e stabilità.','https://www.uscg.mil/Portals/0/BoatingSafety/DOCS/Boaters-Guide-to-Federal-Requirements-for-Receational-Boats-20231108.pdf','U.S. Coast Guard - Safe Loading, 33 CFR 183 Subpart C'),
('61d4754b-b198-42ea-9f82-94c1d818919c','Perché il circuito di aspirazione dell’acqua di mare di un motore entrobordo deve essere controllato prima della partenza?','["Per verificare che presa, filtro e passaggi non siano ostruiti e che il raffreddamento possa funzionare","Per aumentare la pressione del carburante","Per regolare la bussola","Per lubrificare l’invertitore"]',0,'Un’ostruzione nella presa o nel filtro dell’acqua di mare può ridurre il raffreddamento e provocare surriscaldamento. Il controllo va eseguito secondo la procedura del costruttore dell’apparato installato.','https://www.volvopenta.com/support/product-family/md22%20%28inb%29/','Volvo Penta - documentazione motori marini entrobordo'),
('63210b22-c6ee-4cc2-b553-724c7246e817','Qual è la funzione del catalizzatore?','["Favorire la trasformazione chimica di inquinanti presenti nei gas di scarico","Aumentare la coppia alle ruote","Filtrare l’olio motore","Raffreddare il carburante"]',0,'Trattamento catalitico dei gas di scarico.','https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA','Documentazione ufficiale e risorse per il proprietario Subaru Crosstrek'),
('6a509058-9411-4d4c-a0db-d655e85c139c','Qual è la velocità massima dichiarata per la classe Bigliani?','["28 nodi","35 nodi","40 nodi","43 nodi"]',3,'La scheda GdF indica una velocità massima di 43 nodi per la classe Bigliani.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/guardacoste/guardacoste-classe-bigliani','GdF - prestazioni classe Bigliani'),
('6e99d03c-1064-4f5e-8daa-012926c7dcb9','Qual è l''altezza minima da terra dichiarata per la Subaru Crosstrek presentata da Subaru Italia nel 2024?','["180 mm","200 mm","220 mm","245 mm"]',2,'La scheda tecnica pubblicata da Subaru Italia indica un''altezza minima da terra di 220 mm per la nuova Crosstrek descritta nella pagina ufficiale.','https://www.subaru.it/news/nuova-subaru-crosstrek/','Subaru Italia: scheda tecnica, altezza minima da terra'),
('6fdd0040-255a-4c61-b8d1-a2fb4c65ad72','Come viene azionato un turbocompressore tradizionale?','["Dalla pompa ABS","Dal motorino dei tergicristalli","Dalla rotazione delle ruote posteriori","Dall’energia dei gas di scarico che mette in rotazione la turbina collegata al compressore"]',3,'Turbocompressore a gas di scarico.','https://www.landrover.it/defender/defender-110/models-and-specifications.html','Specifiche ufficiali Land Rover Defender 110; dotazioni da verificare in base all’allestimento'),
('75c901a1-bde6-47b7-97e2-6402ebc4afc8','A cosa serve il riduttore/invertitore in una trasmissione marina con linea d’asse?','["A collegare o disinnestare la propulsione, selezionare avanti/folle/indietro e adattare il regime dell’elica a quello del motore","A comandare i fanali di navigazione","A misurare la profondità del fondale","A raffreddare direttamente lo scafo"]',0,'Il riduttore/invertitore trasmette la potenza del motore alla linea d’asse, consente la selezione delle marce avanti, folle e indietro e riduce il regime in funzione dell’elica e della trasmissione.','https://www.volvopenta.com/support/product-family/md22%20%28inb%29/','Volvo Penta - documentazione trasmissioni marine entrobordo'),
('76cc7922-560f-48ef-b972-694984cd77ae','Quale impiego operativo specifico è citato per il B.S.O. 139 nella notizia ufficiale?','["Trasporto passeggeri turistici","Campionamenti e sopralluoghi per la vigilanza ambientale marina","Rimorchio commerciale in porto","Collegamento passeggeri tra isole"]',1,'La Guardia di Finanza indica che il B.S.O. 139 consentirà campionamenti e sopralluoghi per la vigilanza sulla salubrità dell’ambiente marino.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/notizie-ed-eventi/notizie-servizio-navale/anno-2026/potenziata-la-dotazione-di-mezzi-della-2a-squadra-unita-navali-di-vieste-con-lassegnazione-di-un-nuovo-battello-operativo','GdF - impiego istituzionale B.S.O. 139'),
('79385230-9203-40fb-a181-f1588ca22ae6','Qual è la velocità massima che il B.S.O. 139 è in grado di raggiungere secondo la notizia GdF?','["Oltre 25 nodi","Oltre 30 nodi","Oltre 40 nodi","Oltre 50 nodi"]',2,'La notizia ufficiale GdF riporta una velocità superiore a 40 nodi.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/notizie-ed-eventi/notizie-servizio-navale/anno-2026/potenziata-la-dotazione-di-mezzi-della-2a-squadra-unita-navali-di-vieste-con-lassegnazione-di-un-nuovo-battello-operativo','GdF - velocità B.S.O. 139'),
('7f6024e3-274f-4710-8789-1d0cce99a712','Che cosa può indicare un flusso insufficiente dell’acqua di raffreddamento in un motore marino entrobordo?','["Una possibile ostruzione della presa o del filtro, un problema alla pompa o alla girante","Un aumento della capacità del serbatoio","Un funzionamento corretto del circuito","Una maggiore carica della batteria"]',0,'Un flusso ridotto può segnalare un problema nel circuito di raffreddamento, ad esempio un’ostruzione o una girante usurata. Occorre seguire la diagnostica prevista dal costruttore.','https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf','Volvo Penta - principi di raffreddamento dei motori marini'),
('830dc3ee-df01-49d1-ba61-e3af6e853f86','Qual è la funzione dell’intercooler nei motori sovralimentati che ne sono dotati?','["Filtrare l’olio del cambio","Raffreddare l’aria compressa prima dell’aspirazione, aumentando la densità della carica","Ridurre la pressione degli pneumatici","Aumentare la temperatura dell’aria compressa"]',1,'Intercooler e temperatura dell’aria di aspirazione.','https://www.landrover.it/defender/defender-110/models-and-specifications.html','Specifiche ufficiali Land Rover Defender 110; dotazioni da verificare in base all’allestimento'),
('8b540027-0141-4d7f-9116-6c14212967e7','Quale configurazione propulsiva è dichiarata per il B.S.O. 139?','["Un motore entrobordo diesel con linea d’asse","Due motori fuoribordo da 400 HP ciascuno","Un solo motore fuoribordo da 200 HP","Due idrogetti elettrici"]',1,'La notizia ufficiale GdF del 20 aprile 2026 descrive il B.S.O. 139 come battello di 11 metri con due motori fuoribordo da 400 HP ciascuno.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/notizie-ed-eventi/notizie-servizio-navale/anno-2026/potenziata-la-dotazione-di-mezzi-della-2a-squadra-unita-navali-di-vieste-con-lassegnazione-di-un-nuovo-battello-operativo','GdF - scheda ufficiale B.S.O. 139'),
('8ba0917f-8850-4f41-8186-6b7e3ec2ccab','Quale caratteristica distingue il sistema Symmetrical All-Wheel Drive della Crosstrek?','["È una trazione integrale permanente con ripartizione attiva della trazione","Attiva esclusivamente le ruote anteriori in curva","Scollega sempre l''asse posteriore su fondo bagnato","Agisce soltanto sul freno di stazionamento"]',0,'Subaru Italia descrive il Symmetrical AWD come trazione integrale permanente con ripartizione attiva della trazione; il sistema Active Torque Vectoring contribuisce alla manovrabilità in curva.','https://www.subaru.it/news/nuova-subaru-crosstrek/','Subaru Italia: Symmetrical AWD e Active Torque Vectoring'),
('8f6eca28-3cf0-4b7a-90b2-15e545571e6d','Su quali superfici il manuale Wrangler raccomanda di utilizzare le modalità 4H AUTO e 4L?','["Su asfalto asciutto per la guida ordinaria","Esclusivamente in autostrada","Su superfici sconnesse, a bassa aderenza o scivolose, non nella normale marcia su fondo duro","Soltanto durante il traino su strada"]',2,'Il manuale specifica che le posizioni 4H AUTO e 4L sono destinate a superfici sciolte e scivolose, non alla guida normale su superfici dure, dove possono causare usura degli pneumatici e danni alla trasmissione.','https://www.jeep.com/content/dam/cross-regional/stellantis/jeep/latam-rol/colombia/es_co/manuales-propietarios/2024-manual-wrangler-jl-20l-ok.pdf','Jeep - Manuale Wrangler 2024, selezione della trazione 4WD'),
('95172fa4-13d6-415c-b75c-b381b6888f24','Quale autonomia temporale è indicata per il B.S.O. 139 alle diverse andature?','["Circa 6 ore alla massima andatura e oltre 10 ore a velocità di crociera","10 ore alla massima andatura e 6 ore in crociera","2 ore a ogni andatura","24 ore alla massima andatura"]',0,'La notizia ufficiale GdF indica circa 6 ore alla massima andatura e oltre 10 ore a velocità di crociera.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/notizie-ed-eventi/notizie-servizio-navale/anno-2026/potenziata-la-dotazione-di-mezzi-della-2a-squadra-unita-navali-di-vieste-con-lassegnazione-di-un-nuovo-battello-operativo','GdF - autonomia B.S.O. 139'),
('9e0eb0eb-a198-44bf-b6cd-42bb13536aa9','Qual è la funzione del catalizzatore?','["Filtrare l’olio motore","Raffreddare il carburante","Favorire la trasformazione chimica di inquinanti presenti nei gas di scarico","Aumentare la coppia alle ruote"]',2,'Trattamento catalitico dei gas di scarico.','https://www.jeep.com/content/dam/cross-regional/stellantis/jeep/latam-rol/colombia/es_co/manuales-propietarios/2024-manual-wrangler-jl-20l-ok.pdf','Manuale ufficiale Jeep Wrangler 2024'),
('a3c44126-b75d-4ef5-bcdc-f8843b715a1c','A cosa serve la funzione Off Road+ della Jeep Wrangler, se presente nell’allestimento?','["A migliorare il comportamento del veicolo in specifiche modalità fuoristrada, modificando le calibrazioni in funzione della modalità 4WD","Ad aumentare la pressione degli pneumatici","A disattivare il cambio automatico","A sostituire il controllo di stabilità in ogni condizione"]',0,'Il manuale Wrangler descrive Off Road+ come funzione per ottimizzare il comportamento in specifiche modalità fuoristrada; le regolazioni di motore, trasmissione e controllo della trazione variano in base alla modalità 4WD selezionata.','https://www.jeep.com/content/dam/cross-regional/stellantis/jeep/latam-rol/colombia/es_co/manuales-propietarios/2024-manual-wrangler-jl-20l-ok.pdf','Jeep - Manuale Wrangler 2024, Off Road+'),
('a7dd4105-7836-4280-b078-b6e00d40846d','Da quante unità è composta la classe Di Bartolo secondo la scheda GdF?','["2 unità in una serie","7 unità in due serie","19 unità in tre serie","12 unità in quattro serie"]',1,'La scheda ufficiale GdF indica sette unità distinte in due serie (V e VII serie Bigliani).','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/pattugliatore-veloce/pattugliatore-veloce-classe-di-bartolo','GdF - composizione della classe Di Bartolo'),
('aeb4dcd7-615a-4ad9-9404-8fa29346bf7b','Quale autonomia è dichiarata per la classe Di Bartolo alla velocità di crociera indicata?','["2.000 miglia a 18 nodi","1.290 miglia nautiche a 15 nodi","600 miglia a 35 nodi","400 miglia a 10 nodi"]',1,'La scheda GdF riporta un''autonomia di 1.290 miglia nautiche alla velocità di crociera di 15 nodi.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/pattugliatore-veloce/pattugliatore-veloce-classe-di-bartolo','GdF - autonomia classe Di Bartolo'),
('af94535a-3866-4e84-ab0e-c6b795254b27','Quale funzione svolge il radiatore?','["Dissipare verso l’aria il calore del refrigerante","Aumentare la pressione dell’olio","Trasmettere la coppia alle ruote","Alimentare gli iniettori"]',0,'Scambiatore di calore del circuito di raffreddamento.','https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA','Documentazione ufficiale e risorse per il proprietario Subaru Crosstrek'),
('b2ad8db9-57cf-4b33-9b20-1fcde4a78d31','Qual è la funzione della girante nella pompa dell’acqua di raffreddamento di un motore entrobordo?','["Generare il flusso del liquido o dell’acqua previsto dal circuito di raffreddamento","Regolare la tensione della cinghia di ormeggio","Comandare il timone","Filtrare il carburante"]',0,'La girante è l’elemento rotante della pompa che mette in movimento il fluido nel circuito di raffreddamento. Tipo e intervalli di sostituzione dipendono dal motore installato.','https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf','Volvo Penta - pompe e circuiti di raffreddamento marino'),
('b346121a-834f-4b72-8e8a-7390356e3493','Quale funzione svolge il radiatore?','["Trasmettere la coppia alle ruote","Alimentare gli iniettori","Dissipare verso l’aria il calore del refrigerante","Aumentare la pressione dell’olio"]',2,'Scambiatore di calore del circuito di raffreddamento.','https://www.jeep.com/content/dam/cross-regional/stellantis/jeep/latam-rol/colombia/es_co/manuales-propietarios/2024-manual-wrangler-jl-20l-ok.pdf','Manuale ufficiale Jeep Wrangler 2024'),
('b67896ba-094c-410b-8c9e-04ec0bd4b3cf','Perché, prima della navigazione, il carico e le attrezzature di bordo devono essere distribuiti e fissati correttamente?','["Distribuire il peso in modo equilibrato, mantenerlo basso e fissare le attrezzature per impedirne lo spostamento","Concentrare tutto il carico a poppa per aumentare la velocità","Sistemare gli oggetti più pesanti in alto e su un solo lato","Lasciare libero il carico di muoversi per compensare il rollio"]',0,'La guida della U.S. Coast Guard prescrive di distribuire il carico in modo equilibrato, mantenerlo basso e fissare gli oggetti per impedirne lo spostamento: un carico eccessivo o mobile può compromettere assetto e stabilità.','https://www.uscg.mil/Portals/0/BoatingSafety/DOCS/Boaters-Guide-to-Federal-Requirements-for-Receational-Boats-20231108.pdf','U.S. Coast Guard - Safe Loading, 33 CFR 183 Subpart C'),
('b9019675-b6c1-4609-957f-f8d1e9c9ab72','Quale forma di prua caratterizza i pattugliatori multiruolo classe Monti?','["Prua ad ascia (Axe bow)","Prua a bulbo da nave mercantile","Prua piatta da pontone","Prua a vela"]',0,'La Guardia di Finanza descrive la classe Monti come caratterizzata dalla prua ad ascia (Axe bow), associandola alla tenuta al mare e alla capacità di mantenere 28 nodi anche con mare agitato.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/pattugliatore/pattugliatore-classe-monti','GdF - scheda ufficiale pattugliatore classe Monti'),
('ba8c9442-29d2-4770-8758-50f97f59262f','A cosa serve il filtro dell’aria motore?','["A lubrificare i cilindri","A ridurre la pressione dei freni","A trattenere particelle e impurità prima che l’aria entri nel motore","A raffreddare il liquido refrigerante"]',2,'Filtrazione dell’aria di aspirazione.','https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA','Documentazione ufficiale e risorse per il proprietario Subaru Crosstrek'),
('c255e2c1-7db0-4dd9-86fb-1f912d9085cb','Quale funzione offre la scatola di rinvio a due velocità del Defender 110, se installata?','["Consente di selezionare gamme di rapporti alte e ridotte per adattare la trasmissione alle condizioni di marcia","Regola la temperatura del climatizzatore","Sostituisce il differenziale posteriore","Gestisce esclusivamente l’impianto audio"]',0,'La scheda ufficiale Land Rover indica una scatola di rinvio a due velocità; la gamma ridotta è destinata alle condizioni che richiedono controllo e capacità di trazione a bassa velocità. Verificare sempre la configurazione effettiva del mezzo.','https://www.landrover.it/defender/defender-110/models-and-specifications.html','Land Rover Italia - Defender 110, cambio e dinamiche di guida'),
('c966e40a-e4cb-490a-9c33-289d084696f2','Quale cantiere ha costruito i Guardacoste classe Bigliani?','["Cantiere Vittoria S.p.A. di Adria","Intermarine S.p.A.","Fincantieri di Monfalcone","Cantiere di La Spezia"]',1,'La scheda GdF attribuisce la costruzione dei Guardacoste Bigliani al cantiere Intermarine S.p.A.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/guardacoste/guardacoste-classe-bigliani','GdF - cantiere costruttore classe Bigliani'),
('cc3fd3f8-76b3-43e6-b39e-3e7563e49191','Che cosa può indicare un flusso insufficiente dell’acqua di raffreddamento in un motore marino entrobordo?','["Una possibile ostruzione della presa o del filtro, un problema alla pompa o alla girante","Un aumento della capacità del serbatoio","Un funzionamento corretto del circuito","Una maggiore carica della batteria"]',0,'Un flusso ridotto può segnalare un problema nel circuito di raffreddamento, ad esempio un’ostruzione o una girante usurata. Occorre seguire la diagnostica prevista dal costruttore.','https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf','Volvo Penta - principi di raffreddamento dei motori marini'),
('cdc4ef17-6e9c-465f-b63b-e5606b23d166','Quale autonomia è dichiarata per la classe Monti alla velocità di crociera indicata?','["1.290 miglia a 15 nodi","2.000 miglia a 18 nodi","800 miglia a 28 nodi","400 miglia a 10 nodi"]',1,'La scheda GdF riporta un''autonomia di 2.000 miglia nautiche alla velocità di crociera di 18 nodi.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/pattugliatore/pattugliatore-classe-monti','GdF - autonomia classe Monti'),
('dd20650b-d14a-4e29-9d78-3062265ae1cf','Perché il circuito di aspirazione dell’acqua di mare di un motore entrobordo deve essere controllato prima della partenza?','["Per verificare che presa, filtro e passaggi non siano ostruiti e che il raffreddamento possa funzionare","Per aumentare la pressione del carburante","Per regolare la bussola","Per lubrificare l’invertitore"]',0,'Un’ostruzione nella presa o nel filtro dell’acqua di mare può ridurre il raffreddamento e provocare surriscaldamento. Il controllo va eseguito secondo la procedura del costruttore dell’apparato installato.','https://www.volvopenta.com/support/product-family/md22%20%28inb%29/','Volvo Penta - documentazione motori marini entrobordo'),
('dec1e9a0-127a-4127-a283-f20918d5e935','Quale cantiere ha costruito i pattugliatori multiruolo classe Monti?','["Intermarine S.p.A. di Sarzana","Cantiere Vittoria S.p.A. di Adria","Fincantieri di Monfalcone","Cantiere Navale di Viareggio"]',1,'La scheda ufficiale GdF attribuisce la costruzione dei pattugliatori classe Monti al cantiere Vittoria S.p.A. di Adria.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/pattugliatore/pattugliatore-classe-monti','GdF - cantiere costruttore classe Monti'),
('e75e6c34-8539-47ef-b3e0-ea2f3f883c87','Quali modalità di funzionamento prevede il powertrain e-BOXER della Subaru Crosstrek?','["Solo modalità Sport e Neve","Engine driving, EV driving e Motor Assist driving","Solo trazione anteriore e posteriore","Modalità Diesel, Benzina e GPL"]',1,'La documentazione Subaru Italia indica tre modalità di gestione della potenza tra motore termico ed elettrico: Engine driving, EV driving e Motor Assist driving.','https://www.subaru.it/news/nuova-subaru-crosstrek/','Subaru Italia: modalità operative e-BOXER'),
('ed6465d9-f84d-49fb-b672-5e9c65976c6d','Dove è integrato il motore elettrico nel sistema e-BOXER della Subaru Crosstrek?','["Nel differenziale posteriore","All''interno della trasmissione Lineartronic appositamente modificata","Nel serbatoio carburante","Nel mozzo di ciascuna ruota"]',1,'Subaru Italia specifica che il motore elettrico è abbinato al boxer 2.0 ed è integrato nella trasmissione Lineartronic appositamente modificata.','https://www.subaru.it/news/nuova-subaru-crosstrek/','Subaru Italia: integrazione del motore elettrico nella Lineartronic'),
('eebc33a6-7367-4ff3-b32f-bead411c18b8','In quale periodo sono entrate in linea le piattaforme navali della classe Di Bartolo?','["1997-2000","2003-2007","2010-2014","2018-2022"]',1,'La scheda GdF colloca l''entrata in linea delle piattaforme della classe negli anni dal 2003 al 2007.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/pattugliatore-veloce/pattugliatore-veloce-classe-di-bartolo','GdF - periodo di entrata in linea classe Di Bartolo'),
('ef953538-aa0f-4c8e-949c-dcd257e92c00','Qual è il compito del termostato del circuito di raffreddamento?','["Filtrare il carburante","Misurare la pressione degli pneumatici","Regolare il passaggio del refrigerante in funzione della temperatura","Azionare il motorino di avviamento"]',2,'Termostato e controllo della temperatura del motore.','https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA','Documentazione ufficiale e risorse per il proprietario Subaru Crosstrek'),
('f518ce54-9856-4346-b5e0-9fc29665998c','Quale cantiere ha costruito i pattugliatori veloci classe Di Bartolo?','["Cantiere Vittoria S.p.A. di Adria","Intermarine S.p.A. di Sarzana","Fincantieri di Trieste","Cantiere Navale di Ancona"]',1,'La scheda ufficiale del Servizio Navale indica il cantiere Intermarine S.p.A. di Sarzana.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/pattugliatore-veloce/pattugliatore-veloce-classe-di-bartolo','GdF - cantiere costruttore classe Di Bartolo'),
('f805634f-9953-485a-a3c5-26becc351252','Qual è la funzione dell’Hill Descent Control (HDC) sul Defender 110, se presente nell’allestimento?','["Aumentare automaticamente la pressione degli pneumatici","Aiutare a mantenere una velocità controllata nelle discese ripide","Bloccare permanentemente il differenziale anteriore","Sostituire il freno di servizio su strada"]',1,'Land Rover elenca Hill Descent Control tra i sistemi di dinamica del Defender; il sistema assiste il controllo della velocità nelle discese ripide, secondo le condizioni e le istruzioni del manuale del veicolo.','https://www.landrover.it/defender/defender-110/models-and-specifications.html','Land Rover Italia - Defender 110, Hill Descent Control'),
('f88a5314-89e7-44d6-b112-f04a059a7493','Che cosa può indicare un flusso insufficiente dell’acqua di raffreddamento in un motore marino entrobordo?','["Una possibile ostruzione della presa o del filtro, un problema alla pompa o alla girante","Un aumento della capacità del serbatoio","Un funzionamento corretto del circuito","Una maggiore carica della batteria"]',0,'Un flusso ridotto può segnalare un problema nel circuito di raffreddamento, ad esempio un’ostruzione o una girante usurata. Occorre seguire la diagnostica prevista dal costruttore.','https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf','Volvo Penta - principi di raffreddamento dei motori marini'),
('f97f93a7-853e-450e-b85b-71a53f932cdb','Quale sistema di gestione del terreno è indicato nella dotazione tecnica del Defender 110?','["Terrain Response","e-BOXER","X-MODE","Selec-Trac"]',0,'La documentazione ufficiale Land Rover per Defender 110 elenca Terrain Response tra i sistemi di gestione della dinamica e della trazione.','https://www.landrover.it/defender/defender-110/models-and-specifications.html','Land Rover Italia - Defender 110, specifiche e dotazioni'),
('faa2cb48-b714-46b3-b50d-fc91a71e5dc6','Qual è la velocità massima dichiarata per i pattugliatori veloci classe Di Bartolo?','["28 nodi","35 nodi","40 nodi","43 nodi"]',1,'La scheda ufficiale GdF indica una velocità massima di 35 nodi per i pattugliatori veloci classe Di Bartolo.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/pattugliatore-veloce/pattugliatore-veloce-classe-di-bartolo','GdF - dati prestazionali classe Di Bartolo'),
('fab29a77-3079-43d7-95cb-bcb5824eb549','Quale apparato propulsivo è indicato per i Guardacoste classe Bigliani?','["Un motore diesel singolo","Due motori diesel","Due motori elettrici","Un motore a vapore"]',1,'La scheda ufficiale GdF descrive i Guardacoste classe Bigliani come propulsi da due motori diesel.','https://www.gdf.gov.it/it/chi-siamo/organizzazione/specializzazioni/servizio-navale-polizia-del-mare/chi-siamo/flotta-navale/unita-navali-operative/guardacoste/guardacoste-classe-bigliani','GdF - propulsione classe Bigliani'),
('fcd76190-8f7b-42bf-b7bb-62e3ce618931','Quale funzione svolge il radiatore?','["Trasmettere la coppia alle ruote","Alimentare gli iniettori","Dissipare verso l’aria il calore del refrigerante","Aumentare la pressione dell’olio"]',2,'Scambiatore di calore del circuito di raffreddamento.','https://www.landrover.it/defender/defender-110/models-and-specifications.html','Specifiche ufficiali Land Rover Defender 110; dotazioni da verificare in base all’allestimento')
) AS v(id,prompt,options,correct_index,explanation,source_url,source_note)
WHERE b.id=v.id::uuid;

UPDATE public.vehicle_brevetto_question_bank
SET explanation=trim(replace(explanation,' Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.',''))
WHERE active AND explanation LIKE '%Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.%';
COMMIT;
